options.customCss:
/* ============================================================
   Suporte ERP — Agronegociar
   Tema "Registro" para o chat nativo do n8n (@n8n/chat 1.31.0)

   Todas as variaveis e classes daqui foram conferidas contra o
   style.css do pacote oficial. Nada de seletor inventado.

   Cole em: Chat Trigger > Options > Custom CSS
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap');

:root {
  /* --- palheta: papel de escritorio e tinta ---------------- */
  --erp-ink:        #16292E;   /* petroleo profundo: cabecalho e texto */
  --erp-ink-soft:   #2C4147;
  --erp-paper:      #EFF2F0;   /* fundo da conversa, levemente esverdeado */
  --erp-surface:    #FFFFFF;
  --erp-pine:       #0E6B58;   /* unico acento: acao, usuario, links */
  --erp-pine-dark:  #0A5546;
  --erp-pine-wash:  #E4F0EC;
  --erp-muted:      #6B7B7A;
  --erp-hairline:   #DCE3E0;

  /* --- tokens do widget ------------------------------------ */
  --chat--color--primary:    var(--erp-pine);
  --chat--color--secondary:  var(--erp-pine);
  --chat--color-white:       var(--erp-surface);
  --chat--color-light:       var(--erp-paper);
  --chat--color-medium:      var(--erp-hairline);
  --chat--color-dark:        var(--erp-ink);
  --chat--color-disabled:    #A8B6B3;
  --chat--color-typing:      var(--erp-muted);

  /* fala humana em sans, dado de maquina em mono */
  --chat--font-family:            'Instrument Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --chat--font-family--monospace: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  --chat--spacing:        1rem;
  --chat--border-radius:  10px;
  --chat--transition-duration: .18s;

  --chat--window--width:         400px;
  --chat--window--height:        620px;
  --chat--window--border:        1px solid var(--erp-hairline);
  --chat--window--border-radius: 14px;
  --chat--window--z-index:       1000;

  --chat--header--background:    var(--erp-ink);
  --chat--header--color:         var(--erp-surface);
  --chat--header--padding:       1rem 1.15rem;
  --chat--header--border-bottom: none;
  --chat--heading--font-size:    1.0625rem;
  --chat--subtitle--font-size:   .8125rem;
  --chat--subtitle--line-height: 1.45;
  --chat--close--button--color-hover: var(--erp-surface);

  --chat--body--background:        var(--erp-paper);
  --chat--messages-list--padding:  1rem;

  --chat--message--font-size:      13.5px;
  --chat--message-line-height:     1.5;
  --chat--message--padding:        .7rem .875rem;
  --chat--message--border-radius:  14px;
  --chat--message--margin-bottom:  .75rem;

  --chat--message--bot--background: var(--erp-surface);
  --chat--message--bot--color:      var(--erp-ink);
  --chat--message--bot--border:     1px solid var(--erp-hairline);

  --chat--message--user--background: var(--erp-pine);
  --chat--message--user--color:      #F2FBF8;
  --chat--message--user--border:     none;

  --chat--message--pre--background:  var(--erp-paper);
  --chat--message--actions--color:   var(--erp-muted);
  --chat--message--actions--hover:   var(--erp-pine);

  --chat--footer--background: var(--erp-surface);
  --chat--footer--color:      var(--erp-ink);
  --chat--footer--border-top: 1px solid var(--erp-hairline);
  --chat--footer--padding:    .75rem .875rem;

  --chat--input--background:            var(--erp-surface);
  --chat--input--text-color:            var(--erp-ink);
  --chat--input--font-size:             13.5px;
  --chat--input--line-height:           1.5;
  --chat--input--placeholder--font-size: 13.5px;
  --chat--input--padding:               .625rem .75rem;
  --chat--input--border:                1px solid var(--erp-hairline);
  --chat--input--border-active:         1px solid var(--erp-pine);
  --chat--input--border-radius:         10px;
  --chat--textarea--height:             44px;
  --chat--textarea--max-height:         160px;

  --chat--input--container--background:    transparent;
  --chat--input--container--border:         none;
  --chat--input--container--padding:         0;

  --chat--input--send--button--background:       var(--erp-pine);
  --chat--input--send--button--color:            #FFFFFF;
  --chat--input--send--button--background-hover: var(--erp-pine-dark);
  --chat--input--send--button--color-hover:      #FFFFFF;
  --chat--input--button--border-radius:          10px;

  --chat--input--file--button--background:       transparent;
  --chat--input--file--button--color:            var(--erp-muted);
  --chat--input--file--button--background-hover: var(--erp-pine-wash);
  --chat--input--file--button--color-hover:      var(--erp-pine);
  --chat--files-spacing: .5rem;

  --chat--button--background--primary:        var(--erp-pine);
  --chat--button--color--primary:             #FFFFFF;
  --chat--button--border--primary:            1px solid var(--erp-pine);
  --chat--button--background--primary--hover: var(--erp-pine-dark);
  --chat--button--color--primary--hover:      #FFFFFF;
  --chat--button--border--primary--hover:     1px solid var(--erp-pine-dark);
  --chat--button--background--secondary:        transparent;
  --chat--button--color--secondary:             var(--erp-ink);
  --chat--button--border--secondary:            1px solid var(--erp-hairline);
  --chat--button--background--secondary--hover: var(--erp-paper);
  --chat--button--border-radius: 10px;
  --chat--button--padding:       .55rem 1rem;
  --chat--button--font-size:     13.5px;

  --chat--toggle--background:        var(--erp-ink);
  --chat--toggle--hover--background: var(--erp-pine);
  --chat--toggle--active--background: var(--erp-pine-dark);
  --chat--toggle--color:            #FFFFFF;
  --chat--toggle--size:             56px;
  --chat--toggle--border-radius:    14px;
}

/* Cabecalho: titulo apertado e uma regua de tinta no lugar da borda.
   O sublinhado tem a mesma funcao de um traco de livro-caixa. */
.chat-header {
  border-bottom: 2px solid var(--erp-pine);
}
.chat-header h1,
.chat-heading {
  font-weight: 500;
  letter-spacing: -.02em;
  margin: 0;
}
.chat-header p {
  color: #9BB0AB;
  margin: .25rem 0 0;
}

/* O widget ja quadra um canto de cada bolha. Aqui esse canto vira
   quase reto, para a bolha ler como etiqueta em vez de balao. */
.chat-message-from-bot  { border-bottom-left-radius: 2px; }
.chat-message-from-user { border-bottom-right-radius: 2px; }

/* Dado de maquina em mono: ID de chamado, slug, mensagem de erro. */
.chat-message-markdown code,
.chat-message-markdown pre {
  font-family: var(--chat--font-family--monospace);
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
}
.chat-message-markdown code {
  background: var(--erp-paper);
  color: var(--erp-pine-dark);
  padding: 1px 5px;
  border-radius: 4px;
}
.chat-message-from-user .chat-message-markdown code {
  background: var(--erp-pine-dark);
  color: #F2FBF8;
}
.chat-message-markdown pre {
  border: 1px solid var(--erp-hairline);
  border-radius: 8px;
  padding: .75rem;
  overflow-x: auto;
}
.chat-message-markdown a {
  color: var(--erp-pine);
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}
.chat-message-from-user .chat-message-markdown a { color: #C8EBE0; }
.chat-message-markdown p:first-child { margin-top: 0; }
.chat-message-markdown p:last-child  { margin-bottom: 0; }
.chat-message-markdown ol,
.chat-message-markdown ul { margin: .4rem 0; padding-left: 1.15rem; }
.chat-message-markdown li { margin: .2rem 0; }
.chat-message-markdown strong { font-weight: 600; }

/* Prints anexados: evidencia, com nome do arquivo em mono. */
.chat-file {
  font-family: var(--chat--font-family--monospace);
  font-size: 11.5px;
  border: 1px solid var(--erp-pine);
  border-radius: 6px;
  background: var(--erp-surface);
}
.chat-file-name { color: var(--erp-ink); }
.chat-file-delete:hover { color: var(--erp-pine); }

.chat-message-typing-circle { background: var(--erp-muted); }

/* Tela inicial */
.chat-get-started { background: var(--erp-paper); }

.chat-powered-by {
  font-size: 11px;
  color: var(--erp-muted);
}

/* Foco visivel pelo teclado, sem depender de cor sozinha. */
.chat-input:focus-visible,
.chat-input-send-button:focus-visible,
.chat-input-file-button:focus-visible,
.chat-button:focus-visible,
.chat-window-toggle:focus-visible {
  outline: 2px solid var(--erp-pine);
  outline-offset: 2px;
}

.chat-input-send-button {
  transition: background var(--chat--transition-duration) ease;
}

/* Barra de rolagem discreta, no tom do papel. */
.chat-messages-list { scrollbar-width: thin; scrollbar-color: #C4CFCB transparent; }
.chat-messages-list::-webkit-scrollbar { width: 8px; }
.chat-messages-list::-webkit-scrollbar-thumb {
  background: #C4CFCB;
  border-radius: 4px;
}
.chat-messages-list::-webkit-scrollbar-track { background: transparent; }

/* Celular: o operador de campo abre isso no telefone. */
@media (max-width: 480px) {
  :root {
    --chat--window--width: 100vw;
    --chat--window--height: 100dvh;
    --chat--window--border-radius: 0;
    --chat--messages-list--padding: .75rem;
  }
  .chat-message { max-width: 90%; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

